/* ---------- authored lessons (full content). Other lessons render as structured outlines. ---------- */
const LESSONS = {
"networking/m1-l1": {
  minutes: 25,
  what: "A computer network is two or more devices connected so they can exchange data and share resources such as files, printers and an internet connection.",
  why: "Almost every IT role touches a network. When a user says 'the internet is down', the person who understands how the network is built is the one who fixes it quickly.",
  body: `<p>Every network, from two laptops sharing a file to the global internet, has the same four ingredients:</p>
<ul><li><strong>Nodes</strong> — the devices that send or receive data: computers, phones, printers, servers, cameras.</li>
<li><strong>Links</strong> — the media that carry signals between nodes: copper Ethernet cable, fibre, or radio waves (Wi-Fi).</li>
<li><strong>Intermediary devices</strong> — switches, routers and access points that move data towards the right destination.</li>
<li><strong>Rules (protocols)</strong> — agreed formats such as Ethernet, IP and TCP that let devices from different manufacturers understand one another.</li></ul>
<p>Data does not travel as one large file. It is split into small units called <strong>packets</strong>. Each packet carries a source and destination address, so intermediary devices can forward it hop by hop, much as a postal system routes letters by the address on the envelope.</p>`,
  example: "In a small office, ten laptops and a printer connect to a switch. The switch connects to a router, and the router connects to the internet provider. When a laptop prints, its data crosses one switch. When it loads a website, the data crosses the switch, the router and many networks beyond.",
  diagram: "office",
  exercise: "Draw your home or college network. List every node (phones, laptops, smart TV), every link type (cable or Wi-Fi), and every intermediary device. Which single device, if it failed, would disconnect everyone?",
  quiz: [
    { q: "Which device forwards traffic between your home network and the internet provider?", options: ["Switch", "Router", "Printer", "Repeater cable"], answer: 1, why: "A router connects separate networks — here, your LAN and the provider's network." },
    { q: "Why is data split into packets?", options: ["To make files smaller permanently", "So many conversations can share links and lost pieces can be resent", "Because cables can only carry text", "To encrypt the data"], answer: 1, why: "Packets let links be shared fairly and allow individual pieces to be retransmitted." }
  ],
  mistakes: ["Calling every box with blinking lights a 'router' — switches and access points do different jobs.", "Assuming Wi-Fi and the internet are the same thing. Wi-Fi is only the local radio link.", "Forgetting that protocols, not just cables, are what make devices interoperate."],
  summary: "A network is nodes plus links plus intermediary devices, all speaking common protocols. Data moves as addressed packets forwarded hop by hop.",
  further: ["Module 1 lesson 3: Network topologies", "Lab: Packet journey visualizer"]
},
"networking/m2-l1": {
  minutes: 35,
  what: "The OSI (Open Systems Interconnection) model divides network communication into seven layers, each with one job, from physical signals up to the application the user sees.",
  why: "Layers give you a shared vocabulary and a troubleshooting map. 'It's a Layer 1 problem' tells a colleague to check cables before anything else.",
  body: `<p>Read the layers from the bottom up, the way data is built on the wire:</p>
<ol><li><strong>Physical</strong> — bits as electrical, light or radio signals. Cables, connectors, signal strength.</li>
<li><strong>Data Link</strong> — frames between devices on the same network, addressed by MAC address. Switches work here.</li>
<li><strong>Network</strong> — packets between networks, addressed by IP address. Routers work here.</li>
<li><strong>Transport</strong> — segments between applications, identified by port numbers. TCP adds reliability; UDP adds speed.</li>
<li><strong>Session</strong> — opening, maintaining and closing conversations.</li>
<li><strong>Presentation</strong> — data format, compression and encryption (for example, TLS).</li>
<li><strong>Application</strong> — the protocols programs use directly: HTTP, DNS, SMTP.</li></ol>
<p>Each layer adds its own header when sending (<strong>encapsulation</strong>) and removes it when receiving (<strong>decapsulation</strong>). The TCP/IP model used on the real internet merges layers 5–7 into one Application layer and layers 1–2 into Network Access, but the OSI numbers remain the common shorthand.</p>`,
  example: "When you open https://example.com, your browser writes an HTTP request (L7), TLS encrypts it (L6), TCP wraps it in a segment to port 443 (L4), IP adds source and destination addresses (L3), Ethernet or Wi-Fi adds MAC addresses (L2), and the network card sends signals (L1).",
  diagram: "osi",
  exercise: "Open the OSI explorer in the lab. For each layer, name one device or protocol and one problem you would troubleshoot there (for example L1: unplugged cable).",
  quiz: [
    { q: "At which layer does a switch make its forwarding decisions?", options: ["Layer 1", "Layer 2", "Layer 3", "Layer 7"], answer: 1, why: "Switches forward frames based on MAC addresses — Layer 2." },
    { q: "Port numbers belong to which layer?", options: ["Network", "Transport", "Session", "Physical"], answer: 1, why: "TCP and UDP ports identify applications at the Transport layer." }
  ],
  mistakes: ["Memorising layer names without knowing what each one does.", "Thinking the OSI model is a protocol — it is a reference model.", "Placing IP addresses at Layer 2. MAC is Layer 2; IP is Layer 3."],
  summary: "Seven layers, each with a single responsibility. Encapsulation adds headers on the way down; decapsulation removes them on the way up. Troubleshoot from the bottom.",
  further: ["Lab: OSI model explorer", "Module 2 lesson 3: Encapsulation and decapsulation"]
},
"networking/m3-l5": {
  minutes: 45,
  what: "A subnet mask marks which part of an IPv4 address identifies the network and which part identifies the host. Subnetting divides one block into smaller networks.",
  why: "Every address plan, firewall rule and cloud VPC depends on subnetting. Getting it wrong causes overlapping networks, unreachable hosts and wasted address space.",
  body: `<p>An IPv4 address is 32 bits, written as four octets. A prefix such as <code>/26</code> means the first 26 bits are the network portion. The remaining <code>32 − 26 = 6</code> bits are host bits.</p>
<h3>The four-step method</h3>
<ol><li><strong>Host bits</strong>: h = 32 − prefix.</li>
<li><strong>Block size</strong>: 2<sup>h</sup> addresses per subnet.</li>
<li><strong>Network address</strong>: the largest multiple of the block size that is ≤ the address (in the octet where the mask stops).</li>
<li><strong>Broadcast</strong>: network address + block size − 1. Usable hosts sit between them: 2<sup>h</sup> − 2.</li></ol>
<p>Worked example: <code>192.168.10.77/26</code>. h = 6, block = 64. Multiples of 64 in the last octet: 0, 64, 128, 192. 77 falls in the 64 block, so the network is <code>192.168.10.64</code>, broadcast <code>192.168.10.127</code>, usable range <code>.65 – .126</code> (62 hosts). The mask is <code>255.255.255.192</code> because 11000000 = 192.</p>`,
  example: "An office needs four departments of up to 50 devices each from 192.168.10.0/24. A /26 gives 62 usable hosts per subnet and exactly four subnets: .0, .64, .128 and .192.",
  diagram: "subnet",
  exercise: "Without the calculator, find the network, broadcast and usable range for 10.20.30.200/27. Then check your answer in the lab's subnet calculator.",
  quiz: [
    { q: "What is the subnet mask for a /27?", options: ["255.255.255.192", "255.255.255.224", "255.255.255.240", "255.255.255.0"], answer: 1, why: "27 bits = 24 + 3, and 11100000 = 224." },
    { q: "Which is the broadcast address of 172.16.5.130/25?", options: ["172.16.5.127", "172.16.5.255", "172.16.5.128", "172.16.5.254"], answer: 1, why: "/25 blocks are 0–127 and 128–255. 130 is in the second, whose broadcast is .255." }
  ],
  mistakes: ["Forgetting to subtract 2 for the network and broadcast addresses.", "Using the block size from the wrong octet when the prefix is below /24.", "Assigning the network or broadcast address to a host."],
  summary: "Host bits → block size → network (multiple of block) → broadcast (next block − 1). Usable hosts = 2ʰ − 2.",
  further: ["Lab: Subnetting calculator", "Module 3 lesson 9: Practical subnetting exercises"]
},
"cloud-computing/m1-l1": {
  minutes: 25,
  what: "Cloud computing is renting computing resources — servers, storage, databases, networking — on demand over the internet, paying for what you use instead of owning the hardware.",
  why: "Most new applications are deployed to the cloud, and on-premises networks increasingly connect to it. Network and security roles now require cloud fluency.",
  body: `<p>The widely used NIST definition lists five essential characteristics:</p>
<ul><li><strong>On-demand self-service</strong> — create resources yourself through a console or API, without waiting for a person.</li>
<li><strong>Broad network access</strong> — reach those resources over standard networks.</li>
<li><strong>Resource pooling</strong> — the provider shares physical hardware among many customers, isolated from each other.</li>
<li><strong>Rapid elasticity</strong> — scale up or down quickly, sometimes automatically.</li>
<li><strong>Measured service</strong> — usage is metered and billed.</li></ul>
<p>Behind the console are ordinary data centres full of servers, switches and routers. What changes is ownership and control: the provider runs the physical layer, and you control virtual resources through software.</p>`,
  example: "A college fest website expects 50 visitors a day but 20,000 on results day. With cloud hosting, the team adds servers for that one day and removes them afterwards, paying only for the hours used.",
  diagram: "cloud",
  exercise: "Pick an application you use daily. Which of the five characteristics would matter most to the team running it, and why?",
  quiz: [
    { q: "Which characteristic lets you add servers automatically during a traffic spike?", options: ["Measured service", "Rapid elasticity", "Resource pooling", "Broad network access"], answer: 1, why: "Elasticity is the ability to scale capacity up and down with demand." },
    { q: "Is cloud infrastructure 'serverless' in the sense of having no physical servers?", options: ["Yes", "No — the provider operates physical servers you do not manage"], answer: 1, why: "Cloud services always run on physical hardware; the provider simply manages it for you." }
  ],
  mistakes: ["Assuming cloud is automatically cheaper. Always-on, oversized resources can cost more than owned hardware.", "Assuming the provider secures everything. See the shared responsibility model.", "Forgetting that cloud resources still use IP addressing, routing and firewalls."],
  summary: "Cloud = on-demand, metered, elastic resources from a shared provider pool, controlled through software.",
  further: ["Module 1 lesson 6: Shared responsibility model", "Lab: Cloud architecture builder"]
},
"cloud-computing/m1-l6": {
  minutes: 30,
  what: "The shared responsibility model divides security duties between the cloud provider and the customer. The provider secures the cloud itself; the customer secures what they put in it.",
  why: "Many cloud breaches come from customer-side misconfiguration — public storage buckets, open firewall rules, weak credentials — not from failures of the provider.",
  body: `<p>The split moves with the service model:</p>
<ul><li><strong>IaaS</strong> (virtual machines): provider handles facilities, hardware, hypervisor. You handle the OS, patches, applications, data, identities and network rules.</li>
<li><strong>PaaS</strong> (managed databases, app platforms): provider also runs the OS and runtime. You handle application code, data, access and configuration.</li>
<li><strong>SaaS</strong> (email, office suites): provider runs nearly everything. You still own your data, user accounts and access settings.</li></ul>
<p>Across all three, the customer always remains responsible for <strong>data, identities and access configuration</strong>.</p>`,
  example: "A student deploys a database VM with port 5432 open to 0.0.0.0/0. The provider's data centre is fully secure, yet the database is exposed — the firewall rule was the customer's responsibility.",
  diagram: "shared",
  exercise: "For a managed database (PaaS), list three things the provider is responsible for and three you are responsible for.",
  quiz: [
    { q: "In SaaS, who manages which users can access the data?", options: ["The provider only", "The customer", "Nobody"], answer: 1, why: "Identity and access configuration always remains a customer responsibility." },
    { q: "Who patches the hypervisor in IaaS?", options: ["The customer", "The provider"], answer: 1, why: "The hypervisor and physical hosts are part of 'security of the cloud'." }
  ],
  mistakes: ["Believing a managed service means no security work for you.", "Leaving default open network rules in place.", "Not reviewing which identities have administrator access."],
  summary: "Provider: security OF the cloud. Customer: security IN the cloud. Data, identities and access are always yours.",
  further: ["Module 5: Cloud Network Security"]
},
"cloud-computing/m3-l1": {
  minutes: 40,
  what: "A virtual private cloud (VPC on AWS and Google Cloud, VNet on Azure) is an isolated private network inside a cloud provider where you define the address range, subnets and routing.",
  why: "Every cloud workload lives in a virtual network. Its design decides what is reachable from the internet, what stays private and how it connects to other networks.",
  body: `<p>Designing a virtual network uses the same skills as on-premises networking:</p>
<ol><li><strong>Choose a CIDR range</strong> from private space (for example <code>10.20.0.0/16</code>) that will not overlap with offices or other VPCs you may connect later.</li>
<li><strong>Create subnets per availability zone and per tier</strong> — for example a public web subnet and a private app subnet in each of two zones.</li>
<li><strong>Attach route tables</strong>. A public subnet routes <code>0.0.0.0/0</code> to an internet gateway; a private subnet routes it to a NAT gateway (outbound only) or nowhere.</li>
<li><strong>Apply filters</strong> — security groups on interfaces and optional network ACLs on subnets.</li></ol>
<p><em>Cost note:</em> creating a VPC and subnets is free on the major providers, but NAT gateways and some load balancers are billed hourly. The lab simulates them at no cost.</p>`,
  example: "VPC 10.20.0.0/16 → public subnets 10.20.1.0/24 (zone A) and 10.20.2.0/24 (zone B) with a load balancer; private subnets 10.20.11.0/24 and 10.20.12.0/24 for app servers; a database in 10.20.21.0/24 reachable only from the app subnets.",
  diagram: "vpc",
  exercise: "In the cloud architecture builder, place a load balancer, two app servers and a database so the design passes all checks.",
  quiz: [
    { q: "Where should a production database usually be placed?", options: ["Public subnet with a public IP", "Private subnet reachable only from the app tier", "Any subnet, protected by a strong password"], answer: 1, why: "Keeping the database private removes it from the internet-facing attack surface." },
    { q: "Why choose a VPC CIDR that does not overlap your office network?", options: ["It is cheaper", "So the networks can be connected later by VPN or peering", "Overlap is required"], answer: 1, why: "Overlapping ranges make routing between the networks ambiguous." }
  ],
  mistakes: ["Using a tiny CIDR range that cannot grow.", "Putting everything in one public subnet.", "Forgetting a NAT path for private servers that need updates."],
  summary: "A VPC is your private network in the cloud: pick a non-overlapping CIDR, split subnets by zone and tier, route deliberately, filter in layers.",
  further: ["Lab: Cloud architecture builder", "Module 3 lesson 6: Internet and NAT gateways"]
},
"ethical-hacking/m1-l1": {
  minutes: 25,
  what: "Confidentiality, integrity and availability — the CIA triad — are the three properties security tries to protect for any information or system.",
  why: "Every control, finding and risk can be explained by which of the three it protects or threatens. Reports that name the affected property are clearer to readers.",
  body: `<ul><li><strong>Confidentiality</strong> — only authorized people can read the information. Controls: access control, encryption, need-to-know.</li>
<li><strong>Integrity</strong> — information is accurate and changed only in authorized ways. Controls: hashing, digital signatures, change control, input validation.</li>
<li><strong>Availability</strong> — information and services are usable when needed. Controls: redundancy, backups, capacity planning, DDoS protection.</li></ul>
<p>The properties sometimes pull against each other. Encrypting everything with keys stored in one place improves confidentiality but risks availability if that key is lost. Good security balances all three for the system's purpose.</p>`,
  example: "A college results portal: leaked marks break confidentiality; altered marks break integrity; a crash on results day breaks availability.",
  diagram: "cia",
  exercise: "For your email account, write one threat and one control for each of the three properties.",
  quiz: [
    { q: "An attacker changes the amount on an invoice in transit. Which property is violated?", options: ["Confidentiality", "Integrity", "Availability"], answer: 1, why: "The data was modified without authorization." },
    { q: "Regular, tested backups mainly protect:", options: ["Confidentiality", "Availability (and integrity on recovery)", "Neither"], answer: 1, why: "Backups let a service and its correct data be restored after loss." }
  ],
  mistakes: ["Treating security as only confidentiality.", "Adding controls that make a system unusable.", "Ignoring integrity — undetected tampering can be worse than a visible outage."],
  summary: "Protect who can read it (C), whether it is correct (I) and whether it is there when needed (A).",
  further: ["Module 1 lesson 2: Threats, vulnerabilities, and risk"]
},
"ethical-hacking/m1-l8": {
  minutes: 30,
  what: "Ethical hacking is security testing performed with the system owner's explicit, written permission, within an agreed scope and rules of engagement, to help them fix weaknesses.",
  why: "Permission is the difference between a security professional and an offender. In India, unauthorized access to computer systems is an offence under the Information Technology Act, 2000, and most countries have similar laws.",
  body: `<p>Before any testing, a professional engagement defines in writing:</p>
<ul><li><strong>Authorization</strong> — signed by someone with authority over every system in scope.</li>
<li><strong>Scope</strong> — exactly which hosts, address ranges, applications and accounts may be tested, and which may not.</li>
<li><strong>Rules of engagement</strong> — permitted techniques, testing windows, data-handling rules and limits (for example, no denial-of-service).</li>
<li><strong>Contacts and stop conditions</strong> — whom to call if something breaks or a serious issue is found.</li></ul>
<p>In this course you practise only on your own lab machines and intentionally vulnerable applications. That habit — confirm authorization first — is the most important skill you will carry into a security career.</p>`,
  example: "A tester authorized for app.example-client.test notices an unlisted admin server. They stop, record it, and email the client contact to ask whether it is in scope, rather than testing it.",
  diagram: "roe",
  exercise: "Draft a one-page rules-of-engagement document for testing your own home lab VM. Include scope, allowed tools, time window and stop conditions.",
  quiz: [
    { q: "Who can authorize a test of a company's servers?", options: ["Any employee", "Someone with authority over those systems, in writing", "The tester themselves"], answer: 1, why: "Authorization must come from a person entitled to grant it, and be documented." },
    { q: "A critical issue is found mid-test. Per the RoE you should:", options: ["Keep quiet until the final report", "Follow the agreed escalation path to the client contact", "Publish it online"], answer: 1, why: "RoE define urgent escalation so the owner can protect systems quickly." }
  ],
  mistakes: ["Treating a verbal 'go ahead' as authorization.", "Testing an IP that 'looks related' but is not in scope.", "Keeping sensitive client data after the engagement."],
  summary: "No written permission, no test. Scope and rules of engagement decide what, how and when.",
  further: ["Module 9: Penetration Testing Methodology", "Lab: Security report writing"]
},
"ethical-hacking/m7-l5": {
  minutes: 40,
  what: "Injection happens when untrusted input is sent to an interpreter — such as a SQL database, an OS shell or an LDAP server — as part of a command, so the input can change what the command does.",
  why: "Injection has appeared in every edition of the OWASP Top 10. It can expose or alter entire databases, and it is almost entirely preventable with known coding practices.",
  body: `<p>The root cause is mixing <strong>code</strong> and <strong>data</strong> in one string. Compare two ways of looking up a user:</p>
<pre><code>// Vulnerable: input becomes part of the SQL text
query = "SELECT * FROM users WHERE email = '" + input + "'";

// Safe: the query structure is fixed; input is bound as data
query = "SELECT * FROM users WHERE email = ?";
db.execute(query, [input]);</code></pre>
<p>In the first version, specially crafted input can close the quote and add SQL of its own. In the second, the database treats the input purely as a value, whatever characters it contains.</p>
<h3>Defences, in order of importance</h3>
<ol><li><strong>Parameterized queries / prepared statements</strong> or a safe ORM.</li>
<li><strong>Allow-list input validation</strong> (for example, an ID must be digits only).</li>
<li><strong>Least-privilege database accounts</strong> so a flaw exposes as little as possible.</li>
<li><strong>Avoid shell calls</strong> with user input; use library functions instead.</li></ol>`,
  example: "In your isolated lab, an intentionally vulnerable practice application's login form builds SQL by string concatenation. The remediation section of your report recommends prepared statements and shows the corrected code.",
  diagram: "inject",
  exercise: "Review a small code sample of your own (or the sample above) and rewrite every database call to use parameters.",
  quiz: [
    { q: "Why do parameterized queries prevent SQL injection?", options: ["They encrypt the input", "The query structure is fixed before input is supplied", "They block special characters"], answer: 1, why: "Input is bound as data and can never be parsed as SQL." },
    { q: "Escaping quotes manually is best described as:", options: ["The preferred fix", "Fragile and easy to get wrong; use parameters instead"], answer: 1, why: "Manual escaping misses edge cases and differs between databases." }
  ],
  mistakes: ["Relying on front-end validation, which an attacker can bypass.", "Using an admin database account for the web app.", "Showing detailed database errors to users."],
  summary: "Keep code and data separate. Parameterize every query, validate input against an allow-list and limit database privileges.",
  further: ["Module 7 lesson 10: Secure coding and remediation", "OWASP Cheat Sheet Series (owasp.org)"]
}};

